base=[np.ones_like(t), x, v, v**2, v**3, x**2, x*v]
def sc(cc):
    A=np.column_stack(cc); c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
    return np.mean((dv_dt-A@c)**2)/np.var(dv_dt),c
w1s=np.linspace(0.385,0.397,7)
w2s=np.linspace(0.05,3.0,296)
best=(1,None)
for w1 in w1s:
    fc=[np.cos(w1*t),np.sin(w1*t),v*np.cos(w1*t),v*np.sin(w1*t)]
    for w2 in w2s:
        s,_=sc(base+fc+[np.cos(w2*t),np.sin(w2*t)])
        if s<best[0]: best=(s,(w1,w2))
print(best)
